import math
MOD7 = pow(10, 9) + 7
MAXF = pow(10, 5)
my_list = [0] * (MAXF + 1)

def last(l):
	return (l + 1) * l / 2

def get_level_and_index(n):
	idx = -1
	line = -1
	if n == 1:
		return (1, 1)
	left = 2
	right = 1 + math.floor(math.sqrt(2 * n))
	while left <= right:
		line = int((left + right) / 2)
		if last(line) >= n and last(line - 1) < n:
			break
		elif last(line > n):
			right = l - 1
		else:
			left = line + 1
	idx = int(n - line * (line - 1) / 2)
	return (line, idx)

def pow_mod(x, y, p):
	x = x % p
	if x == 0:
		return 0
	res = 1
	while y > 0:
		if y & 1:
			res = res * x
			res = res % p
			y = y - 1
		x = x * x % p
		y = int(y / 2)
	return res

def inv(x, p):
	return pow_mod(x, p - 2, p)

def lci(line, i, p=MOD7):
	x = my_list[line] * inv(my_list[i], p) % p
	y = inv(my_list[line - i], p)
	return x * y % p
my_list[0] = 1
my_list[1] = 1
for i in range(2, MAXF):
	my_list[i] = my_list[i - 1] * i % MOD7
T = int(input())
for _ in range(T):
	(s, e) = map(int, input().split(' '))
	(start_l, start_i) = get_level_and_index(s)
	(end_l, end_i) = get_level_and_index(e)
	line = end_l - start_l
	i = end_i - start_i
	ans = -1
	if line <= 0 or i < 0 or i > line:
		ans = 0
	else:
		ans = lci(line, i)
	print(ans)
